57		}
58		// 原因须说明申请数量、已持仓数量、有效买单剩余量与最大持仓量，且不得出现回绕值。
59		reason := rj.Reason
60		for _, v := range []int64{2, M - 1, 0, M} {
61			if !strings.Contains(reason, strconv.FormatInt(v, 10)) {
62				t.Fatalf("拒绝原因 %q 必须包含数值 %d（申请/已持仓/买单剩余/最大持仓）", reason, v)
63			}
64		}
65		if strings.Contains(reason, strconv.FormatInt(-1, 10)) ||
66			strings.Contains(reason, strconv.FormatInt(math.MinInt64, 10)) {
67			t.Fatalf("拒绝原因不得把回绕后的数值当作真实合计: %q", reason)
68		}
69		// 保留申请合约、限价及已有报价与限额快照。
70		if !rj.QuoteValid || rj.QuoteSeq != 1 || rj.QuoteMoment != 1 || rj.QuotePrice != 1 {
71			t.Fatalf("拒绝记录缺少报价快照: %+v", rj)
72		}
73		if !rj.MaxPositionValid || rj.MaxPosition != M {
74			t.Fatalf("拒绝记录缺少最大持仓量快照: %+v", rj)
75		}
76	
77		if e.Cash() != 2 || e.ReservedCash() != 0 || e.AvailableCash() != 2 ||
78			e.Position("A") != M-1 {
79			t.Fatalf("溢出拒绝不得改变现金/占用/持仓: cash=%d reserved=%d available=%d pos=%d",
80				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"))
81		}
82		if len(e.Orders()) != 2 {
83			t.Fatalf("被拒绝的申请不得生成订单，实际 %d 笔", len(e.Orders()))
84		}
85	
86		// 被拒绝的申请不消耗订单编号：下一笔买单编号仍为 3。
87		ok := mustBuy(t, e, "A", 1, 1)
88		if ok != 3 {
89			t.Fatalf("拒绝不得消耗订单编号，新单应为 3，实际 %d", ok)
90		}
91		// 合计恰好等于限额 M：接受并成交后持仓恰好为 M。
92		if _, err := e.Fill(Trade{TradeID: 3, OrderID: ok, Symbol: "A", Side: Buy, Price: 1, Qty: 1}); err != nil {
93			t.Fatal(err)
94		}
95		if e.Position("A") != M || e.Cash() != 1 || e.ReservedCash() != 0 {
96			t.Fatalf("边界成交后状态错误: cash=%d pos=%d reserved=%d",
97				e.Cash(), e.Position("A"), e.ReservedCash())
98		}
99	}
100	
101	// TestBuyPositionSumOverflowCountsOnlyActiveBuyRemaining 校验计入额度的口径：
102	// 部分成交订单只计未成交部分；已撤销或全部成交的订单不再占用；卖单成交前不抵减持仓。
103	func TestBuyPositionSumOverflowCountsOnlyActiveBuyRemaining(t *testing.T) {
104		M := int64(math.MaxInt64)
105		e, _ := NewEngine(M)
106		mustSetMax(t, e, "A", M)
107		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 1}, 1)
108	
109		// 建仓：买入 M 全部成交，再卖出 3 份 @2 → 持仓 M-3、现金 6。
110		bid := mustBuy(t, e, "A", M, 1)
111		if _, err := e.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "A", Side: Buy, Price: 1, Qty: M}); err != nil {
112			t.Fatal(err)
113		}
114		sid := mustSell(t, e, "A", 3, 2)
115		if _, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell, Price: 2, Qty: 3}); err != nil {
116			t.Fatal(err)
117		}
118	
119		// 买单 2 股，部分成交 1 股：只剩余 1 股计入额度。
120		partial := mustBuy(t, e, "A", 2, 1) // 持仓 M-3 + 剩余 2 = M-1，接受
121		if _, err := e.Fill(Trade{TradeID: 3, OrderID: partial, Symbol: "A", Side: Buy, Price: 1, Qty: 1}); err != nil {
122			t.Fatal(err)
123		}
124		// 此时持仓 M-2、有效买单剩余 1。申请 2 股：M-2+1+2 = M+1 溢出，拒绝。
125		if _, err := e.Buy("A", 2, 1); !errors.Is(err, ErrInt64Overflow) {
126			t.Fatalf("部分成交订单应只计剩余量并致合计溢出，实际 %v", err)
127		}
128		// 申请 1 股：M-2+1+1 = M 恰好允许（不因已成交那 1 股重复计数）。
129		edge := mustBuy(t, e, "A", 1, 1)
130	
131		// 卖单在真正成交前不能抵减持仓：挂一笔卖单不改变买单额度判断。
132		pendingSell := mustSell(t, e, "A", 1, 2)
133		if e.Sellable("A") != M-3 { // 持仓 M-2 减去 1 份未成交卖单占用
134			t.Fatalf("卖单占用可卖数量: sellable=%d", e.Sellable("A"))
135		}
136		// 再申请 1 股：仍按 M-2 + 剩余(1+1) + 1 = M+1 溢出拒绝，卖单未提前抵减持仓。
137		if _, err := e.Buy("A", 1, 1); !errors.Is(err, ErrInt64Overflow) {
138			t.Fatalf("未成交卖单不得抵减持仓额度，实际 %v", err)
139		}
140		if err := e.Cancel(pendingSell); err != nil {
141			t.Fatal(err)
142		}
143	
144		// 成交 edge 1 股：持仓 M-1、partial 仍剩 1。
145		if _, err := e.Fill(Trade{TradeID: 4, OrderID: edge, Symbol: "A", Side: Buy, Price: 1, Qty: 1}); err != nil {
146			t.Fatal(err)
147		}
148		// 再成交 partial 的剩余 1 股：全部成交订单不再占用，持仓恰好 M。
149		if _, err := e.Fill(Trade{TradeID: 5, OrderID: partial, Symbol: "A", Side: Buy, Price: 1, Qty: 1}); err != nil {
150			t.Fatal(err)
151		}
152		if e.Position("A") != M {
153			t.Fatalf("全部成交后持仓应为 M，实际 %d", e.Position("A"))
154		}
155		if o, _ := e.Order(partial); o.Status != StatusFilled {
156			t.Fatalf("partial 应全部成交: %+v", o)
157		}
158		// 持仓已为 M 且限额也是 M：申请 1 股的合计 M+1 本身溢出，按溢出拒绝
159		// （可表示但超限的场景在下方小额引擎中覆盖）。
160		_, err := e.Buy("A", 1, 1)
161		if !errors.Is(err, ErrInt64Overflow) {
162			t.Fatalf("限额为 M 时 M+1 无法表示，必须按溢出拒绝，实际 %v", err)
163		}
164		expectErr(t, err, "委托被拒绝")
165		if e.Position("A") != M {
166			t.Fatalf("拒绝不得改变持仓: %d", e.Position("A"))
167		}
168	
169		// 已撤销订单不占额度：卖出 1 份腾出 1 股后，先挂再撤的买单不影响后续申请。
170		if e.Cash() != 3 { // 建卖 3@2 得 6，此后三次买单成交 @1 共扣 3
171			t.Fatalf("现金余额意外: %d", e.Cash())
172		}
173		rs := mustSell(t, e, "A", 1, 1)
174		if _, err := e.Fill(Trade{TradeID: 6, OrderID: rs, Symbol: "A", Side: Sell, Price: 1, Qty: 1}); err != nil {
175			t.Fatal(err)
176		}
177		if e.Cash() != 4 {
178			t.Fatalf("卖出 1 份后现金应为 4，实际 %d", e.Cash())
179		}
180		// 持仓 M-1。挂 1 股买单（占满额度）再撤销。
181		c := mustBuy(t, e, "A", 1, 1)
182		if err := e.Cancel(c); err != nil {
183			t.Fatal(err)
184		}
185		if e.ReservedCash() != 0 {
186			t.Fatalf("撤销买单后现金占用应清零: %d", e.ReservedCash())
187		}
188		// 撤销后额度释放：再申请 1 股合计恰好 M，接受；申请 2 股溢出拒绝。
189		last := mustBuy(t, e, "A", 1, 1)
190		if _, err := e.Buy("A", 2, 1); !errors.Is(err, ErrInt64Overflow) {
191			t.Fatalf("撤销单不占额度，申请 2 股应因 M-1+2=M+1 溢出拒绝，实际 %v", err)
192		}
193		// 在挂的 last 不受影响。
194		if o, _ := e.Order(last); o.Status != StatusPending || o.Remaining() != 1 {
195			t.Fatalf("拒绝不得影响其他有效订单: %+v", o)
196		}
197	}
198	
199	// TestBuyPositionSumOverflowKeepsOrdinaryRejections 校验其他既有规则不受影响：
200	// 现金不足优先于溢出判断；合计可表示但超限仍走原有原因；恰好等于限额允许。
201	func TestBuyPositionSumOverflowKeepsOrdinaryRejections(t *testing.T) {
202		M := int64(math.MaxInt64)
203		e, _ := NewEngine(M)
204		mustSetMax(t, e, "A", M)
205		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 1}, 1)
206		bid := mustBuy(t, e, "A", M, 1)
207		if _, err := e.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "A", Side: Buy, Price: 1, Qty: M}); err != nil {
208			t.Fatal(err)
209		}
210		// 以 1 卖出 1 份：持仓 M-1、现金仅 1。
211		sid := mustSell(t, e, "A", 1, 1)
212		if _, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell, Price: 1, Qty: 1}); err != nil {
213			t.Fatal(err)
214		}
215		// 申请 2 股：现金不足（需要 2，可用 1）优先，报普通错误，不包装 ErrInt64Overflow。
216		before := len(e.Records())
217		_, err := e.Buy("A", 2, 1)
218		if err == nil {
219			t.Fatal("现金不足必须拒绝")
220		}
221		if errors.Is(err, ErrInt64Overflow) {
222			t.Fatalf("现金不足应走原有拒绝，不得返回 ErrInt64Overflow: %v", err)
223		}
224		expectErr(t, err, "现金不足")
225		if len(e.Records()) != before+1 || e.Records()[before].Reason == "" {
226			t.Fatal("现金不足只追加一条带原因的拒绝记录")
227		}
228		if e.Position("A") != M-1 || e.ReservedCash() != 0 {
229			t.Fatalf("拒绝不得改变状态: pos=%d reserved=%d", e.Position("A"), e.ReservedCash())
230		}
231	
232		// 小额场景：合计可表示但超过限额，仍是原有超限原因。
233		e2, _ := NewEngine(1000)
234		mustSetMax(t, e2, "B", 5)
235		mustQuote(t, e2, "B", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
236		mustBuy(t, e2, "B", 4, 10)
237		_, err = e2.Buy("B", 2, 10)
238		if err == nil || errors.Is(err, ErrInt64Overflow) {
239			t.Fatalf("可表示的超限必须按普通原因拒绝，实际 %v", err)
240		}
241		expectErr(t, err, "超过最大持仓量")
242		mustBuy(t, e2, "B", 1, 10) // 恰好 5，允许
243	}
244	
245	// TestBuyPositionSumOverflowWithAmountLimit 校验金额上限开启时溢出判断依旧生效，
246	// 且拒绝不改变金额上限与任何占用。
247	func TestBuyPositionSumOverflowWithAmountLimit(t *testing.T) {
248		M := int64(math.MaxInt64)
249		e, _ := NewEngine(M)
250		mustSetMax(t, e, "A", M)
251		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 1}, 1)
252		bid := mustBuy(t, e, "A", M, 1)
253		if _, err := e.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "A", Side: Buy, Price: 1, Qty: M}); err != nil {
254			t.Fatal(err)
255		}
256		sid := mustSell(t, e, "A", 1, 2)
257		if _, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell, Price: 2, Qty: 1}); err != nil {
258			t.Fatal(err)
259		}
260		if _, err := e.SetPositionAmountLimit(M); err != nil {
261			t.Fatal(err)
262		}
263		before := len(e.Records())
264		if _, err := e.Buy("A", 2, 1); !errors.Is(err, ErrInt64Overflow) {
265			t.Fatalf("开启金额上限后持仓合计溢出仍必须拒绝，实际 %v", err)
266		}
267		if len(e.Records()) != before+1 {
268			t.Fatal("溢出只能追加一条拒绝记录")
269		}
270		if st := e.PositionAmountStatus(); !st.Enabled || st.Limit != M {
271			t.Fatalf("拒绝不得改变金额上限设置: %+v", st)
272		}
273		if e.Cash() != 2 || e.ReservedCash() != 0 || e.Position("A") != M-1 {
274			t.Fatalf("拒绝不得改变资金与持仓: cash=%d reserved=%d pos=%d",
275				e.Cash(), e.ReservedCash(), e.Position("A"))
276		}
277	}
