648		}
649		// 修改：总量 8、限价 12。
650		mustModify(t, e, id, 8, 12)
651	
652		// 已入账成交重复提交仍返回第一次结果，即使订单后来修改。
653		res2, err := e.Fill(tr)
654		if err != nil {
655			t.Fatal(err)
656		}
657		if res1 != res2 {
658			t.Fatalf("修改后幂等重放必须返回第一次结果: %+v vs %+v", res1, res2)
659		}
660		if e.Cash() != 964 || e.ReservedCash() != 48 || e.Position("A") != 4 {
661			t.Fatalf("幂等重放不得按新参数重新记账: cash=%d reserved=%d pos=%d",
662				e.Cash(), e.ReservedCash(), e.Position("A"))
663		}
664		// 撤销后重放仍旧结果。
665		if err := e.Cancel(id); err != nil {
666			t.Fatal(err)
667		}
668		res3, err := e.Fill(tr)
669		if err != nil {
670			t.Fatal(err)
671		}
672		if res3 != res1 {
673			t.Fatalf("撤销后重放仍须返回第一次结果: %+v vs %+v", res3, res1)
674		}
675	
676		// 尚未入账的成交按处理时有效参数判断：新订单新限价。
677		id2 := mustBuy(t, e, "A", 5, 10)
678		mustModify(t, e, id2, 5, 7)
679		if _, err := e.Fill(Trade{TradeID: 8, OrderID: id2, Symbol: "A", Side: Buy, Price: 8, Qty: 1}); err == nil {
680			t.Fatal("成交必须按修改后的新限价 7 判断")
681		}
682		if _, err := e.Fill(Trade{TradeID: 9, OrderID: id2, Symbol: "A", Side: Buy, Price: 7, Qty: 2}); err != nil {
683			t.Fatalf("符合新限价的成交应入账: %v", err)
684		}
685	}
686	
687	func TestModifyRecordsImmutable(t *testing.T) {
688		e := setupModify(t)
689		id := mustBuy(t, e, "A", 10, 10)
690		mustModify(t, e, id, 8, 12)
691	
692		recs := e.Records()
693		for i := range recs {
694			if recs[i].Kind == RecordModified {
695				recs[i].OldLimit = 1
696				recs[i].OldQty = 1
697				recs[i].Limit = 1
698				recs[i].Qty = 1
699			}
700		}
701		r := lastModifyRecord(t, e)
702		if r.OldLimit != 10 || r.OldQty != 10 || r.Limit != 12 || r.Qty != 8 {
703			t.Fatalf("查询副本篡改不得改写内部修改记录: %+v", r)
704		}
705	
706		// 再次修改与后续报价不得改写历史记录。
707		mustModify(t, e, id, 6, 11)
708		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 20}, 1)
709		var firstMod Record
710		for _, r := range e.Records() {
711			if r.Kind == RecordModified && r.OldQty == 10 {
712				firstMod = r
713				break
714			}
715		}
716		if firstMod.OldLimit != 10 || firstMod.Limit != 12 || firstMod.Qty != 8 ||
717			firstMod.QuotePrice != 10 {
718			t.Fatalf("历史修改记录不得被后续操作改写: %+v", firstMod)
719		}
720	}
721	
722	func TestModifyConcurrentWithFillsAndCancels(t *testing.T) {
723		e, _ := NewEngine(1_000_000)
724		mustSetMax(t, e, "A", 1_000_000)
725		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 1}, 1)
726	
727		const n = 40
728		var ids []int64
729		for i := 0; i < n; i++ {
730			ids = append(ids, mustBuy(t, e, "A", 100, 1)) // 各占用 100
731		}
732	
733		var tradeID atomic.Int64
734		var wg sync.WaitGroup
735		for _, id := range ids {
736			wg.Add(3)
737			go func(id int64) { // 修改：参数可能被额度/剩余量拒绝，忽略错误
738				defer wg.Done()
739				_ = e.Modify(id, 50+id%120, 1)
740			}(id)
741			go func(id int64) { // 成交：超量或撤销后被拒，忽略错误
742				defer wg.Done()
743				for k := 0; k < 3; k++ {
744					_, _ = e.Fill(Trade{
745						TradeID: tradeID.Add(1), OrderID: id, Symbol: "A", Side: Buy, Price: 1, Qty: 30,
746					})
747				}
748			}(id)
749			go func(id int64) { // 撤单
750				defer wg.Done()
751				_ = e.Cancel(id)
752			}(id)
753		}
754		wg.Wait()
755	
756		// 不变量：占用现金 = Σ 有效买单 限价 × 剩余量；现金与持仓和已入账成交一致。
757		var reserved int64
758		for _, o := range e.Orders() {
759			if o.Side != Buy || o.Status == StatusCanceled || o.Status == StatusFilled {
760				continue
761			}
762			reserved += o.Limit * o.Remaining()
763		}
764		if reserved != e.ReservedCash() {
765			t.Fatalf("并发后现金占用不变量被破坏: 计算 %d，实际 %d", reserved, e.ReservedCash())
766		}
767		var tradedCash, tradedQty int64
768		for _, f := range e.fills {
769			tradedCash += f.price * f.qty
770			tradedQty += f.qty
771		}
772		if e.Cash() != 1_000_000-tradedCash {
773			t.Fatalf("并发后现金余额与成交不一致: cash=%d 成交金额=%d", e.Cash(), tradedCash)
774		}
775		if e.Position("A") != tradedQty {
776			t.Fatalf("并发后持仓与成交不一致: pos=%d 成交量=%d", e.Position("A"), tradedQty)
777		}
778		if e.AvailableCash() < 0 {
779			t.Fatal("可用现金不能为负")
780		}
781	}
